(function(){
'use strict';
const FLOW='20260915-natural-fast-v8';
const RESET='20260915-natural-fast-reset-v4';
const RULES='נהלי שיחה: קודם להבין ולהגיב ישירות להודעה האחרונה של הלקוח, ורק אחר כך לקדם את איסוף הפרטים. שאלות כמו מה את ממליצה, למה, מה עדיף וכדומה חייבות לקבל תשובה עניינית ולא חזרה אוטומטית על שאלת שדה חסר. תיקון כמו בעצם/תשני מעדכן את המידע. אין לשאול שוב מידע שכבר נמסר. אחרי מטרת הטיסה משלימים יעד, מועד ומי נוסע; אם חלק נמסר שואלים רק את החסר. רק אחרי שלושתם עוברים לישיר/קונקשן וכבודה יחד, והתקציב אחרון. התשובה צריכה להיות טבעית, קצרה ואנושית.';
function isTrip(){return !!document.getElementById('tripWizard')||location.pathname.indexOf('/trip/new')===0;}
function firstName(p){return String(p.first_name||p.name||p.full_name||'').trim().split(/\s+/)[0]||'';}
function hello(p){const n=firstName(p);return (n?'היי '+n+', ':'היי, ')+'איזה כיף שהתחברת 😊\nאני אריאלה, סוכנת הנסיעות האישית שלך.\nמה מטרת הטיסה? למשל עסקים, בילוי עם חברים, טיול משפחתי או חופשת סקי.';}
function removeLegacy(){document.querySelectorAll('#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar').forEach(x=>x.remove());const w=document.getElementById('tripWizard');if(w)w.style.display='none';}
function style(){if(document.getElementById('ariella-chat-rebuild-style'))return;const s=document.createElement('style');s.id='ariella-chat-rebuild-style';s.textContent=`#tripWizard,#vacationTypeGate,.vacation-type-gate,.vacation-type-grid,.trip-back-bar{display:none!important}#ariellaDesktopChat{width:min(1280px,92%);margin:18px auto 40px;direction:rtl;font-family:Arial,"Segoe UI",sans-serif}#ariellaDesktopChat .ac-shell{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,.85fr);gap:22px}#ariellaDesktopChat .ac-chat,#ariellaDesktopChat .ac-summary{background:#fffaf2;border:1px solid rgba(201,154,63,.38);border-radius:22px;overflow:hidden}#ariellaDesktopChat .ac-chat{height:min(650px,calc(100vh - 150px));min-height:520px;display:flex;flex-direction:column}#ariellaDesktopChat .ac-head{display:flex;align-items:center;gap:10px;padding:10px 14px;background:linear-gradient(135deg,#102b30,#18373a);color:#fff}#ariellaDesktopChat .ac-avatar{width:52px;height:52px;flex:0 0 52px;border:2px solid #fff3cf;border-radius:50%;background:#17353a;overflow:hidden}#ariellaDesktopChat .ariella-avatar-img{display:block!important;width:100%!important;height:100%!important;object-fit:cover!important;object-position:50% 34%!important;border-radius:50%!important;transform:none!important}#ariellaDesktopChat .ac-head-copy{min-width:0;flex:1}#ariellaDesktopChat .ac-head-copy strong{display:block;font-size:16px;white-space:nowrap}#ariellaDesktopChat .ac-online{margin-inline-start:auto;font-size:13px}#ariellaDesktopChat .ac-messages{flex:1;min-height:0;padding:18px 14px;display:flex;flex-direction:column;gap:12px;overflow-y:auto;background:linear-gradient(180deg,#fffdf8,#fbf5e9)}#ariellaDesktopChat .ac-row{display:flex;gap:8px;align-items:flex-start}#ariellaDesktopChat .ac-row.user{justify-content:flex-start;flex-direction:row-reverse}#ariellaDesktopChat .ac-bubble{max-width:84%;padding:11px 13px;border-radius:14px;background:#fff;border:1px solid #eadfc8;white-space:pre-line;line-height:1.55}#ariellaDesktopChat .ac-row.user .ac-bubble{background:#dff3f5;border-color:#b7dde1}#ariellaDesktopChat .ac-mini-avatar{width:34px;height:34px;flex:0 0 34px;border-radius:50%;border:1px solid #d6bf86;background:#17353a;overflow:hidden}#ariellaDesktopChat .ac-compose{padding:10px;border-top:1px solid #eadfc8;background:#fff;display:flex;gap:10px;position:relative;z-index:2}#ariellaDesktopChat textarea{flex:1;min-height:48px;max-height:120px;border:1px solid #d9cdb8;border-radius:14px;padding:12px;font:inherit;resize:none;background:#fff;color:#111;pointer-events:auto!important}#ariellaDesktopChat .ac-send{height:48px;min-width:68px;border:0;border-radius:13px;background:#0b8f9c;color:#fff;font-weight:800;pointer-events:auto!important}#ariellaDesktopChat .ac-summary{padding:18px}#ariellaDesktopChat .ac-detail{padding:9px 0;border-bottom:1px solid #eee5d5}#ariellaDesktopChat .ac-detail b{display:block;color:#17283f}#ariellaDesktopChat .ac-detail span{color:#7f776b;font-size:14px}@media(max-width:899px){#ariellaDesktopChat{width:100%;margin:0 auto 24px;padding:8px 10px}#ariellaDesktopChat .ac-shell{display:flex;flex-direction:column}#ariellaDesktopChat .ac-chat{height:calc(100dvh - 125px);min-height:500px;border-radius:16px}#ariellaDesktopChat .ac-online{display:none}#ariellaDesktopChat .ac-summary{border-radius:16px}}`;document.head.appendChild(s);}
function makeChat(){let c=document.getElementById('ariellaDesktopChat');if(c)return c;const defs=[['destination','יעד'],['dates','תאריכים'],['travelers','נוסעים'],['budget','תקציב'],['flight','טיסה'],['baggage','כבודה']];c=document.createElement('section');c.id='ariellaDesktopChat';c.innerHTML='<div class="ac-shell"><div class="ac-chat"><div class="ac-head"><div class="ac-avatar"></div><div class="ac-head-copy"><strong>אריאלה — סוכנת הנסיעות האישית שלך</strong></div><div class="ac-online">זמינה עכשיו</div></div><div class="ac-messages" id="ariellaChatMessages"></div><div class="ac-compose"><textarea id="ariellaChatInput" rows="1" aria-label="כתיבת הודעה"></textarea><button id="ariellaChatSend" class="ac-send" type="button">שליחה</button></div></div><aside class="ac-summary"><strong>החופשה שלי</strong>'+defs.map(d=>'<div class="ac-detail" data-summary-key="'+d[0]+'"><b>'+d[1]+'</b><span>עדיין לא צוין</span></div>').join('')+'</aside></div>';const w=document.getElementById('tripWizard'),m=document.querySelector('main');if(w&&w.parentNode)w.parentNode.insertBefore(c,w);else if(m)m.appendChild(c);return c;}
const MONTHS={january:'ינואר',february:'פברואר',march:'מרץ',april:'אפריל',may:'מאי',june:'יוני',july:'יולי',august:'אוגוסט',september:'ספטמבר',october:'אוקטובר',november:'נובמבר',december:'דצמבר'};
const WORDS={italy:'איטליה',montenegro:'מונטנגרו',greece:'יוון',thailand:'תאילנד',france:'צרפת',spain:'ספרד',croatia:'קרואטיה',albania:'אלבניה',austria:'אוסטריה',switzerland:'שווייץ',germany:'גרמניה',direct:'טיסה ישירה',connection:'קונקשן',connections:'קונקשן',unlimited:'ללא הגבלת תקציב',carry_on:'טרולי',checked_bag:'מזוודה',personal_item:'תיק יד'};
function he(v){if(v==null)return'';if(Array.isArray(v))return v.map(he).filter(Boolean).join(', ');let s=String(v).trim();const low=s.toLowerCase();if(MONTHS[low])return MONTHS[low];if(WORDS[low])return WORDS[low];Object.keys(MONTHS).forEach(k=>{s=s.replace(new RegExp(k,'ig'),MONTHS[k]);});Object.keys(WORDS).forEach(k=>{s=s.replace(new RegExp('\\b'+k+'\\b','ig'),WORDS[k]);});return s;}
async function loadMemberName(profile){if(firstName(profile))return;try{const r=await fetch('/account',{credentials:'same-origin',cache:'no-store'});if(!r.ok)return;const html=await r.text();const doc=new DOMParser().parseFromString(html,'text/html');const text=(doc.body&&doc.body.innerText)||'';let m=text.match(/שלום\s*[,،:]?\s*([^\s,!.]+)/);if(m&&m[1])profile.first_name=m[1].trim();}catch(e){}}
function controller(chat){if(chat.dataset.ctrl==='1')return;chat.dataset.ctrl='1';const input=chat.querySelector('#ariellaChatInput'),send=chat.querySelector('#ariellaChatSend'),messages=chat.querySelector('#ariellaChatMessages');if(!input||!send||!messages)return;let profile={},history=[],busy=false;try{const s=JSON.parse(localStorage.getItem('ariellaChatState:v4')||'null');if(s){profile=s.profile||{};history=Array.isArray(s.history)?s.history:[];}if(localStorage.getItem('ariellaChatOneTimeReset')!==RESET){const keep={};['first_name','last_name','name','full_name','gender','sex','phone','email','departure_airport'].forEach(k=>{if(profile[k]!=null&&profile[k]!=='')keep[k]=profile[k];});profile=keep;history=[];localStorage.setItem('ariellaChatOneTimeReset',RESET);}else if(!s||s.flow!==FLOW){history=[];}}catch(e){}
const save=()=>{try{localStorage.setItem('ariellaChatState:v4',JSON.stringify({profile,history:history.slice(-80),flow:FLOW,saved_at:new Date().toISOString()}));}catch(e){}};
const add=(who,text)=>{if(!String(text||'').trim())return;const r=document.createElement('div');r.className='ac-row '+who;if(who==='bot'){const a=document.createElement('div');a.className='ac-mini-avatar';r.appendChild(a);}const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;r.appendChild(b);messages.appendChild(r);messages.scrollTop=messages.scrollHeight;};
const summary=()=>{const p=profile,v={destination:he(p.destinations||''),dates:p.departure_date&&p.return_date?he(p.departure_date+' – '+p.return_date):he(p.outbound_month||p.return_month||''),travelers:(p.adults||p.children||p.infants)?`${p.adults||0} מבוגרים${p.children?`, ${p.children} ילדים`:''}${p.infants?`, ${p.infants} תינוקות`:''}`:'',budget:p.budget_mode==='unlimited'?'ללא הגבלת תקציב':(p.budget_amount?`${p.budget_amount} ₪ לאדם`:''),flight:he(p.flight_preference||''),baggage:he(p.baggage||'')};Object.keys(v).forEach(k=>{const el=chat.querySelector(`[data-summary-key="${k}"] span`);if(el)el.textContent=v[k]||'עדיין לא צוין';});};
function purpose(){const greet=hello(profile);add('bot',greet);history.push({role:'assistant',content:greet});save();}
async function start(){messages.innerHTML='';if(history.length){history.forEach(x=>add(x.role==='assistant'?'bot':'user',x.content));summary();return;}await loadMemberName(profile);save();purpose();summary();}
async function sendMessage(raw,display){raw=String(raw||'').trim();if(!raw||busy)return;busy=true;send.disabled=true;input.value='';if(display)add('user',raw);const prior=history.slice(-6);history.push({role:'user',content:raw});save();try{const payload={message:raw,history:prior,profile};const r=await fetch('/api/ariella/chat',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});let data={};try{data=await r.json();}catch(e){}if(!r.ok||data.status!=='success'){add('bot',data.message||'יש כרגע תקלה זמנית. נסו שוב בעוד רגע.');return;}profile=data.profile||profile;summary();const reply=String(data.reply||'').trim();if(reply){add('bot',reply);history.push({role:'assistant',content:reply});}save();}catch(e){add('bot','יש כרגע תקלה זמנית. נסו שוב בעוד רגע.');}finally{busy=false;send.disabled=false;input.focus();}}
send.addEventListener('click',e=>{e.preventDefault();sendMessage(input.value,true);});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage(input.value,true);}});input.disabled=false;send.disabled=false;start();}
function patchFetch(){if(window.__ariellaPatched)return;window.__ariellaPatched=true;const old=window.fetch.bind(window);window.fetch=async function(input,init){const url=typeof input==='string'?input:(input&&input.url)||'';if(/\/api\/ariella\/chat(?:\?|$)/.test(url)&&init&&typeof init.body==='string'){try{const p=JSON.parse(init.body),m=String(p.message||'').trim();if(m)p.message=m+'\n\n'+RULES;init=Object.assign({},init,{body:JSON.stringify(p)});}catch(e){}}return old(input,init);};}
function boot(){if(!isTrip())return;removeLegacy();style();patchFetch();controller(makeChat());}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();